def call_with_retry(fn):
    for attempt in range(5):
        try:
            return fn()
        except ServiceUnavailable:
            time.sleep(2 ** attempt)        # 1, 2, 4, 8, 16 s
    raise

# 1,000 app instances call the same API; it has a 10-second outage.

